using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using SolicitudIT_Isertec.Data; using System.Diagnostics;
namespace SolicitudIT_Isertec.Controllers; public class HomeController:Controller { private readonly AppDbContext db; public HomeController(AppDbContext db)=>this.db=db;
 [Authorize] public async Task<IActionResult> Index(){ var uid=int.Parse(User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)!.Value); var role=User.FindFirst(System.Security.Claims.ClaimTypes.Role)!.Value; var vm=new DashboardVm{Role=role,Total=role=="usuario"?await db.Solicitudes.CountAsync(x=>x.UsuarioId==uid):await db.Solicitudes.CountAsync(),Pendientes=role=="usuario"?await db.Solicitudes.CountAsync(x=>x.UsuarioId==uid&&(x.Estado==Models.EstadoSolicitud.pendiente||x.Estado==Models.EstadoSolicitud.asignada)):await db.Solicitudes.CountAsync(x=>x.Estado==Models.EstadoSolicitud.pendiente),EnProceso=role=="usuario"?await db.Solicitudes.CountAsync(x=>x.UsuarioId==uid&&x.Estado==Models.EstadoSolicitud.en_proceso):await db.Solicitudes.CountAsync(x=>x.Estado==Models.EstadoSolicitud.en_proceso)}; return View(vm); }
 [AllowAnonymous] public IActionResult Error()=>View(); }
public class DashboardVm{public string Role{get;set;}="";public int Total{get;set;}public int Pendientes{get;set;}public int EnProceso{get;set;}}
